import sys
from collections import defaultdict, deque

def topological_sort(packages, dependencies):
    graph = defaultdict(list)
    in_degree = {pkg: 0 for pkg in packages}

    for pkg, deps in dependencies.items():
        for dep in deps:
            graph[dep].append(pkg)
            in_degree[pkg] += 1

    queue = deque([pkg for pkg in in_degree if in_degree[pkg] == 0])
    sorted_order = []

    while queue:
        queue = deque(sorted(queue))
        node = queue.popleft()
        sorted_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(sorted_order) == len(packages):
        return sorted_order
    else:
        return None

def main():
    input = sys.stdin.read().strip().split('\n')
    index = 0

    while index < len(input):
        n = int(input[index])
        if n == 0:
            break
        packages = []
        dependencies = {}

        for i in range(n):
            line = input[index + i + 1].split()
            pkg = line[0]
            deps = line[1:]
            packages.append(pkg)
            dependencies[pkg] = deps

        index += n + 1

        result = topological_sort(packages, dependencies)
        if result:
            for pkg in result:
                print(pkg)
        else:
            print('cannot be ordered')
        if index < len(input):
            print()

main()
